import {prepare,RATE,COUNTDOWN} from './codec.js';
import {paint,Timeline} from './render.js';
const $=id=>document.getElementById(id);
let cachedText=null,cached=null,version=0,running=false,raf=0,lock=null,controller=null;
function duration(s){if(s<10)return `${Math.ceil(s*10)/10} sec`;if(s<60)return `${Math.ceil(s)} sec`;return `${Math.floor(s/60)} min ${Math.ceil(s%60)} sec`;}
function notice(s=''){$('notice').hidden=!s;$('notice').textContent=s;}
function prep(text){if(text!==cachedText){cachedText=text;cached=prepare(text);}return cached;}
async function estimate(){const id=++version,text=$('message').value;$('play').disabled=true;$('transmit-note').textContent=text?'Preparing…':'Your words stay here.';try{const p=await prep(text);if(id!==version)return;$('transmit-note').textContent=`${COUNTDOWN} sec setup + ~${duration(p.seconds)} sending`;$('transmit-note').title=`${p.displays} patterns including recovery${p.compressed?' and lossless compression':''}.`;$('play').disabled=false;}catch(e){if(id===version&&text)$('transmit-note').textContent=e.message;}}
$('message').addEventListener('input',estimate);$('message').addEventListener('change',estimate);estimate();
function mode(name){controller?.abort();for(const m of ['transmit','decode']){$(`${m}-tab`).setAttribute('aria-pressed',String(m===name));$(`${m}-panel`).hidden=m!==name;}notice();}
$('transmit-tab').onclick=()=>mode('transmit');$('decode-tab').onclick=()=>mode('decode');
$('about-button').onclick=()=>$('about').showModal();$('close-about').onclick=()=>$('about').close();
function draw(record,index){const canvas=$('lights');paint(canvas,record,index,{size:Math.min(1800,Math.max(640,Math.round(canvas.getBoundingClientRect().width*(devicePixelRatio||1))))});}
function stop(){running=false;cancelAnimationFrame(raf);$('stage').hidden=true;$('app').inert=false;lock?.release().catch(()=>{});lock=null;$('play').focus();}
$('stop').onclick=stop;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('stage').hidden)stop();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){stop();notice('Transmission stopped when the page left the foreground. Press Play to restart.');}});
async function startTransmission(){let p;try{p=await prep($('message').value);}catch(e){notice(e.message);return;}notice();running=true;$('stage').hidden=false;$('completion').hidden=true;$('app').inert=true;$('stop').textContent='Stop ×';$('stop').focus();draw(null,0);navigator.wakeLock?.request('screen').then(l=>{if(running)lock=l;else l.release();}).catch(()=>{});const start=performance.now()+COUNTDOWN*1000,timeline=new Timeline(p.displays,RATE,start);function tick(now){if(!running)return;if(now<start)$('stage-status').textContent=`Start recording · ${Math.ceil((start-now)/1000)}`;else{const i=timeline.next(now);if(i!==null){draw(p.records[i%p.records.length],i);$('stage-status').textContent=`${timeline.stalled?'Running slower':'Sending'} · ~${duration((p.displays-i)/RATE)} left`;}if(now>=timeline.end){running=false;draw(null,0);$('completion').hidden=false;$('stage-status').textContent='Transmission complete';$('stop').textContent='Done';lock?.release().catch(()=>{});lock=null;return;}}raf=requestAnimationFrame(tick);}raf=requestAnimationFrame(tick);}
$('play').onclick=()=>startTransmission().catch(e=>{stop();notice(`Could not start transmission: ${e.message}`);});
$('open-text').onclick=()=>$('text-file').click();$('text-file').onchange=async()=>{const f=$('text-file').files[0];$('text-file').value='';if(!f)return;try{$('message').value=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());estimate();notice();}catch{notice('Choose a UTF-8 text document or code file.');}};
function view(name){for(const id of ['upload-area','working','result-area'])$(id).hidden=id!==name;}
$('choose').onclick=()=>$('video-file').click();$('another').onclick=()=>{view('upload-area');$('video-file').click();};$('cancel').onclick=()=>controller?.abort();
$('video-file').onchange=async()=>{const f=$('video-file').files[0];$('video-file').value='';if(!f)return;controller?.abort();const current=new AbortController();controller=current;notice();view('working');$('progress').value=0;$('decode-status').textContent='Opening recording…';try{const {analyze}=await import('./analyze.js?v=2.0.0');const out=await analyze(f,{signal:current.signal,onProgress:p=>{if(controller!==current)return;$('progress').value=p.fraction;$('decode-status').textContent=`${p.mode} · ${Math.round(p.fraction*100)}%${p.total?` · ${p.received} of ${p.total} units`:''}`;}});if(controller!==current)return;if(out.result!==null){$('result').value=out.result;view('result-area');$('copy').focus();}else{view('upload-area');notice(out.total?`Recovered ${out.received} of ${out.total} units. Too much information was missing to verify the document. Record from the countdown through completion with the whole square sharp.`:'No complete message found. For recordings made before version 2, open the earlier-format decoder from Help.');}}catch(e){if(controller===current){view('upload-area');if(!current.signal.aborted)notice(e.message);}}finally{if(controller===current)controller=null;}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('result').value);$('copy').textContent='Copied';setTimeout(()=>$('copy').textContent='Copy ⧉',1800);}catch{$('result').focus();$('result').select();notice('Text selected. Use your device’s Copy command.');}};
